import heapq


def stable_toposort(graph):
    nodes = list(graph.keys())
    node_set = set(nodes)

    # Validate: raise ValueError for missing dependencies
    for node, deps in graph.items():
        for dep in deps:
            if dep not in node_set:
                raise ValueError(f"Missing dependency: {dep}")

    # Insertion-order index for tie-breaking
    index = {node: i for i, node in enumerate(nodes)}

    # In-degree = number of (unresolved) dependencies
    in_degree = {node: len(deps) for node, deps in graph.items()}

    # Reverse adjacency: dependency -> [nodes that depend on it]
    dependents = {node: [] for node in nodes}
    for node, deps in graph.items():
        for dep in deps:
            dependents[dep].append(node)

    # Min-heap keyed by insertion index for stable ordering
    heap = [(index[node], node) for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        _, node = heapq.heappop(heap)
        result.append(node)
        for dependent in dependents[node]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, (index[dependent], dependent))

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result
